PARAMS = ['E0','kout','Smax','SC50']
def predict(df, p):
    def solve_one(dose, times):
        times = np.asarray(times, float)
        tg = np.linspace(0, max(times.max(),1e-6), 2001)
        c = pk_conc(dose, tg)
        kin = p['E0']*p['kout']*0 + p['E0']*p['kout']
        f = kin*(1 + p['Smax']*c/(p['SC50']+c))
        k = p['kout']; dt = tg[1]-tg[0]; a = np.exp(-k*dt)
        R = np.empty_like(tg); R[0]=p['E0']; acc=0.0
        for i in range(1,len(tg)):
            acc = acc*a + 0.5*dt*(f[i-1]*a + f[i])
            R[i] = p['E0']*np.exp(-k*tg[i]) + acc
        return np.interp(times, tg, R)
    return per_dose(df, solve_one)

PARAMS = ['E0','kout','Imax','IC50']
def predict(df, p):
    def solve_one(dose, times):
        times = np.asarray(times, float)
        tg = np.linspace(0, max(times.max(),1e-6), 2001)
        c = pk_conc(dose, tg)
        kel = p['kout']*(1 + p['Imax']*c/(p['IC50']+c))
        kin = p['E0']*p['kout']
        R = np.empty_like(tg); R[0]=p['E0']; dt = tg[1]-tg[0]
        for i in range(1,len(tg)):
            # semi-implicit exponential step
            kk = 0.5*(kel[i-1]+kel[i])
            R[i] = (R[i-1]*np.exp(-kk*dt) + kin*dt) if False else R[i-1] + dt*(kin - kel[i-1]*R[i-1])
            R[i] = R[i-1] + dt*0.5*((kin - kel[i-1]*R[i-1]) + (kin - kel[i]*R[i]))/1.0 if False else R[i]
        return np.interp(times, tg, R)
    return per_dose(df, solve_one)

